-- cpd-migration: breaking after 52
-- The head branch of the pull request cpd adopted (contract §2.2 "An adopted PR", §4.4, §4.5 `pr-adopt`; pro-n8):
-- null for a cpd PR, non-null means adopted. Set at insert only; one live PR per head branch of a repo. The
-- history triggers of `prs` are regenerated by the runner's reconcile.
ALTER TABLE prs ADD COLUMN head_ref TEXT CHECK (head_ref IS NULL OR length(head_ref) BETWEEN 1 AND 255);

CREATE TRIGGER prs_head_ref_fixed BEFORE UPDATE OF head_ref ON prs
BEGIN SELECT RAISE(ABORT, 'pr_locked'); END;

CREATE UNIQUE INDEX prs_head_ref_live ON prs (repo, head_ref) WHERE head_ref IS NOT NULL AND status IN ('waiting', 'dispatch', 'open');
